import {useEffect, useMemo, useState} from 'react';
import {ComboBox} from '../../../components/common/ComboBox';
import type {SearchResult} from '../../search/searchTypes';

type PolicyStatus='no_previous_policy'|'had_previous_policy'|'new_vehicle';
type OwnershipMode='unchanged'|'no_discount'|'same_plate'|'other_plate';
type Usage={key:string;label:string};
type Model={key:string;label:string;category:string;category_key:string;brand:string;brand_key:string;model:string;imported:boolean|null;usages:Usage[]};
type Catalog={models:Model[];insurers:{key:string;label:string}[];production_years_jalali:number[];durations:number[];discounts:number[];fuels:{key:string;label:string}[];coverages_toman:number[]};
type Preview={provider:string;status:string};

const policyLabels:Record<PolicyStatus,string>={no_previous_policy:'بیمه‌نامهٔ قبلی ندارد',had_previous_policy:'بیمه‌نامهٔ قبلی دارد',new_vehicle:'خودروی نو / صفرکیلومتر'};
const ownershipLabels:Record<OwnershipMode,string>={unchanged:'تعویض پلاک یا انتقال تخفیف نداشته',no_discount:'تعویض پلاک؛ تخفیف قابل انتقال ندارم',same_plate:'تعویض پلاک؛ تخفیف همین پلاک حفظ می‌شود',other_plate:'انتقال تخفیف از پلاک دیگر'};
const faDigits=(value:string)=>value.replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632));
const dateText=(value:string)=>faDigits(value).trim().replace(/-/g,'/');
const validDate=(value:string)=>{const normalized=dateText(value);if(!/^(13|14)\d\d\/(0[1-9]|1[0-2])\/(0[1-9]|[12]\d|3[01])$/.test(normalized))return false;const [,month,day]=normalized.split('/').map(Number);return day<=(month<=6?31:30)};
const number=(value:number)=>value.toLocaleString('fa-IR');
const unique=<T extends {key:string}>(items:T[])=>[...new Map(items.map(item=>[item.key,item])).values()];

export function ThirdCarWizard({onResult,onStart}:{onResult:(result:SearchResult)=>void;onStart:()=>void}){
  const [catalog,setCatalog]=useState<Catalog|null>(null),[step,setStep]=useState(0),[error,setError]=useState(''),[pending,setPending]=useState(false);
  const [categoryKey,setCategoryKey]=useState(''),[brandKey,setBrandKey]=useState(''),[modelKey,setModelKey]=useState(''),[usage,setUsage]=useState(''),[year,setYear]=useState(1404);
  const [fuel,setFuel]=useState('1'),[imported,setImported]=useState<'catalog'|'true'|'false'>('catalog');
  const [status,setStatus]=useState<PolicyStatus>('no_previous_policy'),[insurer,setInsurer]=useState(''),[start,setStart]=useState(''),[expiry,setExpiry]=useState(''),[release,setRelease]=useState(''),[newExpiry,setNewExpiry]=useState('');
  const [previousDuration,setPreviousDuration]=useState(12),[ownershipMode,setOwnershipMode]=useState<OwnershipMode>('unchanged'),[policyOwner,setPolicyOwner]=useState<'current'|'previous'|'transfer'>('current'),[supplement,setSupplement]=useState(false);
  const [transferPlate,setTransferPlate]=useState(''),[transfer,setTransfer]=useState({part1:'',part2:'',part3:'',serial:'',national:'',relationship:'',inquiry:''});
  const [thirdDiscount,setThirdDiscount]=useState(0),[driverDiscount,setDriverDiscount]=useState(0),[hadClaim,setHadClaim]=useState(false),[counts,setCounts]=useState({property:0,bodily:0,driver:0});
  const [duration,setDuration]=useState(12),[coverage,setCoverage]=useState(70_000_000);
  const [baseCompany,setBaseCompany]=useState(''),[baseStart,setBaseStart]=useState(''),[baseExpiry,setBaseExpiry]=useState('');
  const [previews,setPreviews]=useState<Preview[]>([]),[previewLoading,setPreviewLoading]=useState(false);

  useEffect(()=>{const controller=new AbortController();fetch('/api/search/catalog',{signal:controller.signal}).then(async response=>{if(!response.ok)throw Error('اطلاعات فرم دریافت نشد.');return response.json()}).then((data:Catalog)=>{
    setCatalog(data);const initial=data.models.find(item=>item.key==='peugeot_pars')||data.models[0];if(initial){setCategoryKey(initial.category_key);setBrandKey(initial.brand_key);setModelKey(initial.key);setUsage(initial.usages[0]?.key||'')}
    if(data.production_years_jalali.length)setYear(data.production_years_jalali[0]);if(data.fuels.length)setFuel(data.fuels[0].key);if(data.coverages_toman.includes(70_000_000))setCoverage(70_000_000);
  }).catch(reason=>{if(!controller.signal.aborted)setError(reason.message)});return()=>controller.abort()},[]);

  const model=catalog?.models.find(item=>item.key===modelKey);
  const categoryChoices=useMemo(()=>unique((catalog?.models||[]).map(item=>({key:item.category_key,label:item.category}))),[catalog]);
  const categoryModels=(catalog?.models||[]).filter(item=>item.category_key===categoryKey);
  const brandChoices=unique(categoryModels.map(item=>({key:item.brand_key,label:item.brand})));
  const brandModels=categoryModels.filter(item=>item.brand_key===brandKey).sort((a,b)=>a.model.localeCompare(b.model,'fa'));
  const effectiveImported=imported==='catalog'?!!model?.imported:imported==='true';
  function selectModel(next:Model|undefined){if(!next)return;setCategoryKey(next.category_key);setBrandKey(next.brand_key);setModelKey(next.key);setUsage(next.usages[0]?.key||'');setPreviews([])}
  function changeCategory(key:string){selectModel((catalog?.models||[]).find(item=>item.category_key===key))}
  function changeBrand(key:string){selectModel(categoryModels.find(item=>item.brand_key===key))}

  function payload(){
    const history=status==='no_previous_policy'?{status}:status==='new_vehicle'?{status,first_use_date_jalali:dateText(release)||null,new_vehicle_expiry_jalali:dateText(newExpiry)||null}:{status,previous_insurer_key:insurer||null,previous_start_date_jalali:dateText(start)||null,previous_expiry_date_jalali:dateText(expiry)||null,previous_duration_months:previousDuration,no_claim_discount_percent:thirdDiscount,driver_discount_percent:driverDiscount,had_claim:hadClaim,property_claim_count:hadClaim?counts.property:0,bodily_claim_count:hadClaim?counts.bodily:0,driver_claim_count:hadClaim?counts.driver:0,ownership_mode:ownershipMode,policy_owner:policyOwner,supplement_discounts:policyOwner==='transfer'&&supplement,...(ownershipMode==='other_plate'?{transfer_plate:transferPlate||null,transfer_plate_part1:transfer.part1||null,transfer_plate_part2:transfer.part2||null,transfer_plate_part3:transfer.part3||null,transfer_plate_serial:transfer.serial||null,transfer_national_id:transfer.national||null,transfer_relationship:transfer.relationship,transfer_inquiry_id:transfer.inquiry||null}:{})};
    return {product:'third_car',vehicle:{category_key:model?.category_key,brand_key:model?.brand_key,model_key:modelKey,usage_key:usage,production_year_jalali:year,fuel_type_key:fuel,imported:imported==='catalog'?null:effectiveImported,construction_year_title:String(year)},previous_policy:history,duration_months:duration,financial_coverage_toman:coverage,sabim_zero_km_third_discount:status==='new_vehicle',sabim_zero_km_driver_discount:status==='new_vehicle',sabim_history:status!=='had_previous_policy'&&baseCompany&&validDate(baseStart)&&validDate(baseExpiry)?{insurer_key:baseCompany,start_date_jalali:dateText(baseStart),expiry_date_jalali:dateText(baseExpiry)}:null};
  }
  const serialized=model?JSON.stringify(payload()):'';
  useEffect(()=>{if(step!==3||!serialized)return;const controller=new AbortController();setPreviewLoading(true);setPreviews([]);const timer=setTimeout(()=>fetch('/api/search/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:serialized,signal:controller.signal}).then(async response=>{if(!response.ok)throw Error('اطلاعات فرم معتبر نیست؛ بخش‌های قبلی را بازبینی کن.');return response.json()}).then(data=>{setPreviews(data.providers);setError('')}).catch(reason=>{if(!controller.signal.aborted)setError(reason.message)}).finally(()=>{if(!controller.signal.aborted)setPreviewLoading(false)}),180);return()=>{clearTimeout(timer);controller.abort()}},[serialized,step]);

  function validate(currentStep=step){
    if(currentStep===0){if(!model||model.category_key!==categoryKey||model.brand_key!==brandKey)return'نوع، برند و مدل خودرو را کامل انتخاب کن.';if(!model.usages.some(item=>item.key===usage))return'کاربری خودرو را انتخاب کن.'}
    if(currentStep===1){if(status==='had_previous_policy'){if(!insurer)return'شرکت بیمهٔ قبلی را انتخاب کن.';if(!validDate(start)||!validDate(expiry))return'شروع و پایان بیمه‌نامهٔ قبلی را با تاریخ شمسی معتبر وارد کن.';if(dateText(start)>=dateText(expiry))return'پایان بیمه‌نامهٔ قبلی باید پس از شروع آن باشد.';if(ownershipMode==='other_plate'&&(!transferPlate.trim()||![transfer.part1,transfer.part2,transfer.part3,transfer.serial,transfer.national,transfer.inquiry].every(Boolean)))return'مشخصات پلاک و مالک مبدأ انتقال تخفیف را کامل کن.'}if(status==='new_vehicle'&&(!validDate(release)||!validDate(newExpiry)))return'تاریخ ترخیص و پایان بیمه‌نامهٔ خودروی نو را کامل کن.'}
    if(currentStep===2){if(status==='had_previous_policy'&&hadClaim&&!Object.values(counts).some(Boolean))return'دست‌کم یکی از تعداد خسارت‌ها باید بیشتر از صفر باشد.';if(status!=='had_previous_policy'){if(!baseCompany||!validDate(baseStart)||!validDate(baseExpiry))return'اطلاعات تکمیلی لازم برای استعلام را کامل کن.';if(dateText(baseStart)>=dateText(baseExpiry))return'پایان بازه باید پس از شروع آن باشد.'}}
    return'';
  }
  function next(){const problem=validate();if(problem){setError(problem);return}setError('');setStep(value=>value+1)}
  async function search(){const problem=validate(2);if(problem){setError(problem);return}if(previewLoading||!allReady){setError('استعلام هر چهار منبع هنوز آماده نیست؛ اطلاعات مراحل قبل را بازبینی کن.');return}setPending(true);setError('');onStart();try{const response=await fetch('/api/search',{method:'POST',headers:{'Content-Type':'application/json'},body:serialized});if(!response.ok)throw Error(response.status===422?'اطلاعات فرم یا تاریخ‌ها معتبر نیست.':'اتصال به سرور برقرار نشد.');onResult(await response.json())}catch(reason){setError(reason instanceof Error?reason.message:'استعلام ناموفق بود.')}finally{setPending(false)}}

  const dateField=(label:string,value:string,setter:(value:string)=>void)=><label>{label}<input value={value} onChange={event=>setter(event.target.value)} placeholder="۱۴۰۴/۰۱/۰۱" inputMode="numeric" dir="ltr" aria-invalid={!!value&&!validDate(value)}/>{value&&!validDate(value)&&<small className="field-error">تاریخ را به‌شکل ۱۴۰۴/۰۱/۰۱ وارد کن.</small>}</label>;
  const months=(value:number,setter:(value:number)=>void,label:string)=><label>{label}<select value={value} onChange={event=>setter(Number(event.target.value))}>{catalog?.durations.map(item=><option key={item} value={item}>{number(item)} ماه</option>)}</select></label>;
  const readyCount=previews.filter(item=>item.status==='ready').length;
  const allReady=previews.length===4&&readyCount===4;

  return <section className="wizard" aria-label="فرم بیمه شخص ثالث خودرو"><div className="wizard-top"><span>استعلام شخص ثالث خودرو</span><span>گام {number(step+1)} از ۴</span></div><div className="progress"><span style={{width:`${(step+1)*25}%`}}/></div><fieldset disabled={pending} className="wizard-fields">
    {step===0&&<div className="question"><span className="avatar">۱</span><h2>مشخصات خودرو</h2><div className="answer"><ComboBox label="نوع خودرو" choices={categoryChoices} value={categoryKey} onChange={changeCategory} disabled={!catalog}/><ComboBox label="برند خودرو" choices={brandChoices} value={brandKey} onChange={changeBrand} disabled={!catalog}/><ComboBox label="مدل خودرو" choices={brandModels.map(item=>({key:item.key,label:item.model||item.label}))} value={modelKey} onChange={key=>selectModel(brandModels.find(item=>item.key===key))} disabled={!catalog}/><label>کاربری<select value={usage} onChange={event=>setUsage(event.target.value)}>{model?.usages.map(item=><option key={item.key} value={item.key}>{item.label}</option>)}</select></label><label>سال ساخت<select value={year} onChange={event=>setYear(Number(event.target.value))}>{catalog?.production_years_jalali.map(item=><option key={item} value={item}>{number(item)}</option>)}</select></label><details className="optional-section full"><summary>جزئیات تکمیلی خودرو (اختیاری)</summary><div className="answer"><label>نوع سوخت<select value={fuel} onChange={event=>setFuel(event.target.value)}>{catalog?.fuels.map(item=><option key={item.key} value={item.key}>{item.label}</option>)}</select></label><label>محل تولید<select value={imported} onChange={event=>setImported(event.target.value as typeof imported)}><option value="catalog">انتخاب خودکار</option><option value="false">داخلی</option><option value="true">وارداتی</option></select></label></div></details></div></div>}

    {step===1&&<div className="question"><span className="avatar">۲</span><h2>سابقهٔ بیمه‌نامه و مالکیت</h2><div className="answer"><label>وضعیت بیمه‌نامهٔ قبلی<select value={status} onChange={event=>setStatus(event.target.value as PolicyStatus)}>{Object.entries(policyLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label>{status==='new_vehicle'&&<>{dateField('تاریخ ترخیص / اولین استفاده',release,setRelease)}{dateField('تاریخ پایان بیمه‌نامهٔ اولیه',newExpiry,setNewExpiry)}</>}{status==='had_previous_policy'&&<><ComboBox label="شرکت بیمهٔ قبلی" choices={catalog?.insurers||[]} value={insurer} onChange={setInsurer}/>{dateField('شروع بیمه‌نامهٔ قبلی',start,setStart)}{dateField('پایان بیمه‌نامهٔ قبلی',expiry,setExpiry)}{months(previousDuration,setPreviousDuration,'مدت بیمه‌نامهٔ قبلی')}<label>وضعیت پلاک و انتقال تخفیف<select value={ownershipMode} onChange={event=>setOwnershipMode(event.target.value as OwnershipMode)}>{Object.entries(ownershipLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>بیمه‌نامهٔ قبلی به نام چه کسی است؟<select value={policyOwner} onChange={event=>setPolicyOwner(event.target.value as typeof policyOwner)}><option value="current">مالک فعلی</option><option value="previous">مالک قبلی</option><option value="transfer">انتقال‌دهندهٔ تخفیف</option></select></label>{policyOwner==='transfer'&&<label className="check-field"><input type="checkbox" checked={supplement} onChange={event=>setSupplement(event.target.checked)}/>تخفیف انتقالی به تخفیف فعلی اضافه شود</label>}{ownershipMode==='other_plate'&&<div className="subform full"><h3>مشخصات مبدأ انتقال تخفیف</h3><div className="answer"><label>شماره پلاک کامل<input value={transferPlate} onChange={event=>setTransferPlate(faDigits(event.target.value))}/></label>{([['part1','بخش اول پلاک'],['part2','حرف پلاک'],['part3','بخش سوم پلاک'],['serial','سریال پلاک'],['national','کد ملی صاحب پلاک'],['relationship','نسبت با بیمه‌گذار'],['inquiry','شناسهٔ استعلام پلاک']] as const).map(([key,label])=><label key={key}>{label}<input value={transfer[key]} onChange={event=>setTransfer({...transfer,[key]:faDigits(event.target.value)})}/></label>)}</div></div>}</>}</div></div>}

    {step===2&&<div className="question"><span className="avatar">۳</span><h2>تخفیف، خسارت و پوشش</h2><div className="answer">{status==='had_previous_policy'&&<><label>درصد تخفیف شخص ثالث<select value={thirdDiscount} onChange={event=>setThirdDiscount(Number(event.target.value))}>{catalog?.discounts.map(item=><option key={item} value={item}>{number(item)}٪</option>)}</select></label><label>درصد تخفیف حوادث راننده<select value={driverDiscount} onChange={event=>setDriverDiscount(Number(event.target.value))}>{catalog?.discounts.map(item=><option key={item} value={item}>{number(item)}٪</option>)}</select></label><label>از بیمه‌نامهٔ قبلی خسارت گرفته‌ای؟<select value={hadClaim?'yes':'no'} onChange={event=>setHadClaim(event.target.value==='yes')}><option value="no">خیر</option><option value="yes">بله</option></select></label>{hadClaim&&(['property','bodily','driver'] as const).map(kind=><label key={kind}>تعداد خسارت {({property:'مالی',bodily:'جانی',driver:'راننده'})[kind]}<select value={counts[kind]} onChange={event=>setCounts({...counts,[kind]:Number(event.target.value)})}>{[0,1,2,3].map(item=><option key={item} value={item}>{item===3?'۳ یا بیشتر':number(item)}</option>)}</select></label>)}</>}{months(duration,setDuration,'مدت بیمه‌نامهٔ جدید')}<label>تعهد مالی<select value={coverage} onChange={event=>setCoverage(Number(event.target.value))}>{catalog?.coverages_toman.map(item=><option key={item} value={item}>{number(item)} تومان</option>)}</select></label>{status!=='had_previous_policy'&&<><ComboBox label="شرکت بیمهٔ ثبت‌شده" choices={catalog?.insurers||[]} value={baseCompany} onChange={setBaseCompany}/>{dateField('شروع بازهٔ ثبت‌شده',baseStart,setBaseStart)}{dateField('پایان بازهٔ ثبت‌شده',baseExpiry,setBaseExpiry)}</>}</div></div>}

    {step===3&&<div className="question"><span className="avatar">✓</span><h2>مرور و دریافت پیشنهادها</h2><div className="review"><span><b>{model?.category} · {model?.brand} · {model?.model} · {model?.usages.find(item=>item.key===usage)?.label} · {number(year)}</b><button type="button" className="secondary" onClick={()=>setStep(0)}>ویرایش خودرو</button></span><span><b>{policyLabels[status]}{status==='had_previous_policy'?` · ${insurer} · ${dateText(start)} تا ${dateText(expiry)}`:status==='new_vehicle'?` · ترخیص ${dateText(release)}`:''}</b><button type="button" className="secondary" onClick={()=>setStep(1)}>ویرایش سابقه</button></span><span><b>{number(duration)} ماه · {number(coverage)} تومان{status==='had_previous_policy'?` · تخفیف ثالث ${number(thirdDiscount)}٪ · راننده ${number(driverDiscount)}٪`:''}</b><button type="button" className="secondary" onClick={()=>setStep(2)}>ویرایش پوشش</button></span></div><p className="preview-summary">{previewLoading?'در حال آماده‌سازی استعلام…':allReady?'استعلام هر چهار منبع آماده است.':readyCount?`${number(readyCount)} منبع آماده است؛ اطلاعات مراحل قبل را بازبینی کن.`:'اطلاعات استعلام هنوز کامل نیست.'}</p></div>}
    {error&&<p className="alert" role="alert">{error}</p>}<div className="wizard-actions">{step>0&&<button type="button" className="secondary" onClick={()=>{setError('');setStep(value=>value-1)}}>مرحلهٔ قبل</button>}{step<3?<button type="button" className="primary" onClick={next}>ادامه</button>:<button type="button" className="primary" onClick={search} disabled={pending||previewLoading||!allReady}>{pending?'در حال استعلام…':'دریافت پیشنهادها'}</button>}</div>
  </fieldset></section>;
}
